Visibility.example:
// A sneaking contest: the least visible player wins.
const { DerivedPlayerStat, Player } = kcds.players;

const visibility = (one) => one.derivedStat(DerivedPlayerStat.Visibility);
const winner = Player.all().sort((a, b) => visibility(a) - visibility(b))[0];

