CarriedWeight.example:
const { DerivedPlayerStat } = kcds.players;

const load = player.derivedStat(DerivedPlayerStat.CarriedWeight);
const capacity = player.derivedStat(DerivedPlayerStat.InventoryCapacity);
if (load > capacity) {
  kcds.core.Chat.sendToPlayer(player, 'You carry too much.');
}

